package com.example.demo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class DemoApplication {

    public static void main(String[] args) {
        SpringApplication.run(DemoApplication.class, args);
    }

}

package com.example.demo;

public interface NameRepository {

    String findName(long id);

}

package com.example.demo;

import java.util.Map;
import org.springframework.stereotype.Repository;

@Repository
public class InMemoryNameRepository implements NameRepository {

    private static final Map<Long, String> NAMES = Map.of(
            1L, "Alice",
            2L, "Bob");

    @Override
    public String findName(long id) {
        return NAMES.getOrDefault(id, "World");
    }

}

package com.example.demo;

import org.springframework.stereotype.Service;

@Service
public class GreetingService {

    private final NameRepository nameRepository;

    public GreetingService(NameRepository nameRepository) {
        this.nameRepository = nameRepository;
    }

    public String greet(long id) {
        return "Hello, " + nameRepository.findName(id) + "!";
    }

}

package com.example.demo;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.BDDMockito.given;
import static org.mockito.Mockito.verify;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class GreetingServiceTest {

    @Mock
    private NameRepository nameRepository;

    @InjectMocks
    private GreetingService greetingService;

    @Test
    void greetUsesNameFromRepository() {
        given(nameRepository.findName(1L)).willReturn("Alice");

        String greeting = greetingService.greet(1L);

        assertThat(greeting).isEqualTo("Hello, Alice!");
        verify(nameRepository).findName(1L);
    }

}

package com.example.demo;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

@SpringBootTest
class DemoApplicationTests {

    @Autowired
    private GreetingService greetingService;

    @Test
    void contextLoads() {
        assertThat(greetingService).isNotNull();
    }

    @Test
    void greetingIsWiredThroughTheApplicationContext() {
        assertThat(greetingService.greet(2L)).isEqualTo("Hello, Bob!");
    }

}

